#!/usr/bin/env python3
# run66: find an EXPLICIT associator decomposition of jdef(E+X,Y)-jdef(X,Y) so that each
# term is a matrix associator [P,Q,R]=P(QR)-(PQ)R with E in at least one slot (=> 0 by
# E-nuclearity). We verify the diff lies in the two-sided ideal generated by E-associators
# by checking: under the rewrite that sets EVERY E-associator to 0 (i.e. force E to associate),
# the diff is 0. Python already confirmed assoc-collapse=0. Here we produce a STEP LIST:
# express jdef A Y for A=E+X by multilinear expansion in the 3 A-slots of the degree-3 form,
# then group E-containing brackets. We output the count of E-monomials and confirm that
# applying the 3 directed nuclearity rewrites (LA: E(PQ)->(EP)Q ; MA: (PE)Q->P(EQ) ;
# RA: (PQ)E->P(QE)) repeatedly to a CANONICAL right-comb normal form makes diff vanish.
import sys
sys.setrecursionlimit(1000000)

def pmul(P,Q):
    r={}
    for ta,ca in P.items():
        for tb,cb in Q.items():
            t=('*',ta,tb); r[t]=r.get(t,0)+ca*cb
    return {k:v for k,v in r.items() if v}
def padd(*Ps):
    r={}
    for P in Ps:
        for k,v in P.items(): r[k]=r.get(k,0)+v
    return {k:v for k,v in r.items() if v}
def pneg(P): return {k:-v for k,v in P.items()}
def jb(P,Q): return padd(pmul(P,Q), pmul(Q,P))
def jdef(A,Y):
    AA=jb(A,A); return padd(jb(jb(A,Y),AA), pneg(jb(A,jb(Y,AA))))

E={'E':1}; X={'X':1}; Y={'Y':1}
diff=padd(jdef(padd(E,X),Y), pneg(jdef(X,Y)))

# Canonical rewrite to RIGHT-COMB form using FULL associativity but ONLY where a node has E
# at its association junction. Simplest sound model for "E nuclear": E associates with
# everything, X and Y do NOT. We normalize a tree by repeatedly applying, anywhere:
#   (a*b)*c -> a*(b*c)   ONLY IF the moved factor across the junction is E-bearing in a way
# nuclearity licenses. Precise: E nuclear means for ANY P,Q: E(PQ)=(EP)Q, (PE)Q=P(EQ),
# (PQ)E=P(QE). i.e. an E that is a DIRECT operand of an inner product can hop the bracket.
# Implement: rewrite leaf-adjacent E hops to a normal form; iterate to fixpoint; then compare.
def is_leaf(t): return isinstance(t,str)
def rewrite_once(t):
    # returns (newt, changed)
    if is_leaf(t): return t,False
    l,r=t[1],t[2]
    # LA: E*(P*Q) -> (E*P)*Q   when l=='E'
    if l=='E' and not is_leaf(r):
        return ('*',('*','E',r[1]),r[2]),True
    # RA: (P*Q)*E -> P*(Q*E)   when r=='E'
    if r=='E' and not is_leaf(l):
        return ('*',l[1],('*',l[2],'E')),True
    # MA: (P*E)*Q -> P*(E*Q)   when l=('*',P,'E')
    if not is_leaf(l) and l[2]=='E':
        return ('*',l[1],('*','E',r)),True
    # recurse
    nl,c1=rewrite_once(l)
    if c1: return ('*',nl,r),True
    nr,c2=rewrite_once(r)
    if c2: return ('*',l,nr),True
    return t,False
def norm(t):
    seen=0
    while True:
        t2,c=rewrite_once(t)
        if not c: return t
        t=t2; seen+=1
        if seen>10000: return t
def norm_poly(P):
    r={}
    for t,c in P.items():
        k=norm(t); r[k]=r.get(k,0)+c
    return {k:v for k,v in r.items() if v}

nd=norm_poly(diff)
print("diff monomials (raw):", len(diff))
print("diff monomials after E-nuclearity normal form:", len(nd))
if not nd:
    print("  ✓✓ pieceB CLOSES BY E-NUCLEARITY ALONE (matrix level) — no octonion alternativity needed.")
    print("  => Lean route: same as gmat_drop — express via associators, kill E-slots by hL/hM/hR.")
else:
    print("  ✗ residual after E-nuclearity (sample):")
    for k,v in list(nd.items())[:30]:
        print("    ",v,k)
